import { ref } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
export default {
  __name: 'AddPlanDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const formRef = ref(null);
    const form = ref({
      id: null,
      name: null,
      type: null,
      size: null,
      time: null,
      num: null,
      velocity: null,
      container1: null,
      container2: null,
      container2Ip: null
    });

    // ✅ 只设置 required，无触发方式
    const rules = {
      name: [{
        required: true,
        message: '请输入名称',
        trigger: 'manual'
      }],
      type: [{
        required: true,
        message: '请选择类型',
        trigger: 'manual'
      }],
      container1: [{
        required: true,
        message: '请输入容器1',
        trigger: 'manual'
      }],
      container2: [{
        required: true,
        message: '请输入容器2',
        trigger: 'manual'
      }],
      container2Ip: [{
        required: true,
        message: '请输入容器2 IP',
        trigger: 'manual'
      }],
      size: [{
        required: true,
        message: '请输入大小',
        trigger: 'manual'
      }],
      time: [{
        required: true,
        message: '请输入时间',
        trigger: 'manual'
      }],
      num: [{
        required: true,
        message: '请输入数量',
        trigger: 'manual'
      }],
      velocity: [{
        required: true,
        message: '请输入速度',
        trigger: 'manual'
      }]
    };

    // ✅ 手动打开对话框（供父组件调用）
    const openDialog = () => {
      dialogVisible.value = true;
    };
    __expose({
      openDialog
    });

    // ✅ 根据类型清空无关字段
    const handleTypeChange = () => {
      form.value.size = null;
      form.value.time = null;
      form.value.num = null;
      form.value.velocity = null;
      form.value.container1 = null;
      form.value.container2 = null;
      form.value.container2Ip = null;
    };

    // ✅ 提交表单时手动触发验证
    const submitForm = () => {
      formRef.value.validate(async valid => {
        if (valid) {
          try {
            const response = await axios.post('http://localhost:8081/plan/add', form.value);
            if (response.data === '添加成功') {
              ElMessage.success('添加成功');
              dialogVisible.value = false;
            } else {
              ElMessage.warning(response.data);
            }
          } catch (error) {
            ElMessage.error('添加失败');
            console.error(error);
          }
        }
      });
    };
    const __returned__ = {
      dialogVisible,
      formRef,
      form,
      rules,
      openDialog,
      handleTypeChange,
      submitForm,
      ref,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
